using System;using System.IO;using System.Linq;using UnityEditor;using UnityEditor.SceneManagement;using UnityEngine;using UnityEngine.Rendering;using UnityEngine.Rendering.Universal;using UnityEngine.SceneManagement;using GameActions;using FirstPerson;using UDK7M;
namespace AssetPipeline.Editor
{
 [InitializeOnLoad]public static class AdvancedVFXReviewSetup
 {
  public const string ScenePath="Assets/Game/VFX/Combat/Advanced/Preview/AdvancedCombatVFXReview.unity";const string Root="Assets/Game/VFX/Combat/Advanced/",Stage="AssetStaging/VFXPhase2/";
  static AdvancedVFXReviewSetup(){EditorApplication.update+=()=>{if(EditorApplication.isCompiling||EditorApplication.isUpdating||EditorApplication.isPlayingOrWillChangePlaymode||!File.Exists(Stage+"ReviewScene.request"))return;File.Delete(Stage+"ReviewScene.request");try{Run();File.WriteAllText(Stage+"review_scene.json","{\"passed\":true}");}catch(Exception e){File.WriteAllText(Stage+"review_scene.json",e.ToString());Debug.LogException(e);}};}
  static Material Mat(string name,Color c){string path=Root+"Materials/"+name+".mat";var m=AssetDatabase.LoadAssetAtPath<Material>(path);if(!m){m=new Material(Shader.Find("Universal Render Pipeline/Lit"));m.SetColor("_BaseColor",c);AssetDatabase.CreateAsset(m,path);}return m;}
  static GameObject Box(string name,Vector3 p,Vector3 scale,Material material){var g=GameObject.CreatePrimitive(PrimitiveType.Cube);g.name=name;g.transform.position=p;g.transform.localScale=scale;g.GetComponent<Renderer>().sharedMaterial=material;return g;}
  static void Run()
  {
   Directory.CreateDirectory(Root+"Preview");var prior=SceneManager.GetActiveScene();var scene=EditorSceneManager.NewScene(NewSceneSetup.EmptyScene,NewSceneMode.Additive);SceneManager.SetActiveScene(scene);var selection=Selection.objects;
   try
   {
    var library=AdvancedCombatVFXLibrary.Load();if(!library)throw new Exception("VFX library not ready");var floor=Mat("ReviewCheckerFloor",Color.white);floor.SetTexture("_BaseMap",AssetDatabase.LoadAssetAtPath<Texture2D>("Assets/Game/VFX/Combat/Preview/ReviewChecker.asset"));floor.SetTextureScale("_BaseMap",new Vector2(5,5));Box("Opaque checker floor",new Vector3(0,-.15f,0),new Vector3(32,.3f,32),floor);var white=Mat("ReviewWhite",new Color(.6f,.62f,.65f));var dark=Mat("ReviewDark",new Color(.03f,.035f,.04f));Box("Opaque reference wall",new Vector3(0,5,10),new Vector3(26,10,.2f),white);for(int i=-12;i<=12;i+=2)Box("Straight vertical reference",new Vector3(i,4.5f,9.85f),new Vector3(.08f,9,.05f),dark);for(int i=1;i<=8;i+=2)Box("Straight horizontal reference",new Vector3(0,i,9.8f),new Vector3(25,.06f,.05f),dark);
    RenderSettings.ambientMode=AmbientMode.Flat;RenderSettings.ambientLight=new Color(.18f,.19f,.22f);var sun=new GameObject("Review key light").AddComponent<Light>();sun.type=LightType.Directional;sun.transform.rotation=Quaternion.Euler(45,-35,0);sun.intensity=1.5f;sun.shadows=LightShadows.None;
    var camera=new GameObject("Main Camera").AddComponent<Camera>();camera.tag="MainCamera";camera.transform.SetPositionAndRotation(new Vector3(10,6,-13),Quaternion.LookRotation(new Vector3(-10,-4,16)));camera.nearClipPlane=.03f;camera.farClipPlane=120;camera.fieldOfView=55;camera.allowHDR=true;var data=camera.GetUniversalAdditionalCameraData();data.requiresColorTexture=data.requiresDepthTexture=true;data.renderPostProcessing=true;var volume=new GameObject("Review bloom and tone mapping").AddComponent<Volume>();volume.isGlobal=true;string profilePath=Root+"Preview/ReviewVolume.asset";var profile=AssetDatabase.LoadAssetAtPath<VolumeProfile>(profilePath);if(!profile){profile=ScriptableObject.CreateInstance<VolumeProfile>();profile.Add<Bloom>().intensity.Override(.6f);profile.Add<Tonemapping>().mode.Override(TonemappingMode.ACES);AssetDatabase.CreateAsset(profile,profilePath);}volume.sharedProfile=profile;
    var raw=AssetDatabase.LoadAssetAtPath<GameObject>("Assets/Game/Enemies/UDK7M/Prefabs/UDK7M.prefab");var machine=(GameObject)PrefabUtility.InstantiatePrefab(raw,scene);machine.name="Review UDK7M";machine.transform.position=new Vector3(-5,0,5);foreach(var a in machine.GetComponentsInChildren<Animator>(true))a.enabled=false;foreach(var a in machine.GetComponentsInChildren<MonoBehaviour>(true))a.enabled=false;foreach(var a in machine.GetComponentsInChildren<AudioSource>(true))a.enabled=false;var boss=machine.AddComponent<UDK7MBoss>();boss.enabled=false;boss.tuning=AssetDatabase.LoadAssetAtPath<UDK7MTuning>("Assets/Game/Enemies/UDK7M/AI/UDK7M_ThreePhase.asset");var encounter=new GameObject("Review feedback only").AddComponent<UDK7MArena>();encounter.enabled=false;encounter.boss=boss;encounter.tuning=boss.tuning;encounter.feedback=encounter.gameObject.AddComponent<UDK7MFeedback>();encounter.feedback.tuning=boss.tuning;boss.arena=encounter;var presentation=machine.AddComponent<UDK7MPresentation>();presentation.boss=boss;presentation.library=library;
    var model=(GameObject)PrefabUtility.InstantiatePrefab(AssetDatabase.LoadAssetAtPath<GameObject>("Assets/Game/Player/Gauntlet/Prefabs/GauntletViewModel.prefab"),scene);model.name="Review gauntlet";model.transform.position=new Vector3(5,2,2);foreach(var a in model.GetComponentsInChildren<Gauntlet.GauntletCameraMotion>(true))a.enabled=false;var combat=model.AddComponent<GauntletCombat>();combat.animationPlayer=model.GetComponent<Gauntlet.GauntletAnimationPlayer>();combat.externalInputEnabled=true;var energy=model.AddComponent<WeaponEnergyVFXController>();energy.combat=combat;energy.library=library;energy.preview=true;energy.previewCharge=1;
    var demo=new GameObject("Advanced VFX review controls").AddComponent<AdvancedVFXDemo>();demo.library=library;demo.machine=presentation;demo.weapon=energy;EditorSceneManager.SaveScene(scene,ScenePath);AssetDatabase.SaveAssets();
   }finally{Selection.objects=selection.Where(x=>x).ToArray();SceneManager.SetActiveScene(prior);EditorSceneManager.CloseScene(scene,true);}
  }
 }
}
